insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('grounding-anchors-card', 'Grounding Anchors Card', 'dbt'::resource_kind, 'A wallet card of the client''s own five-senses anchors for coming back to the present.', 'Give the client a rehearsed way back to the room when the past floods in.', array['Adults', 'Teens']::text[], '15 minutes to build, then in the moment', 'Build it from things the client actually has to hand: a keyring texture, a scent, a phrase, the feel of their feet. Rehearse it in session while calm and again when mildly activated, so the card is a memory of having done it rather than a set of instructions. Keep it small enough to carry.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see right now"}, {"id": "f1", "type": "textarea", "label": "Four things I can touch, and how they feel"}, {"id": "f2", "type": "textarea", "label": "Three sounds I can hear"}, {"id": "f3", "type": "textarea", "label": "Two things I can smell or taste"}, {"id": "f4", "type": "textarea", "label": "One thing I say to myself: today is (date), I am in (place), I am safe enough"}, {"id": "f5", "type": "textarea", "label": "The anchor that works fastest for me"}, {"id": "f6", "type": "textarea", "label": "Who I can text once I am back"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-map', 'Window of Tolerance Map', 'worksheet'::resource_kind, 'A drawing of the client''s calm zone, their overwhelmed zone and their shut-down zone, with the signs of each.', 'Give the client and clinician a shared picture of activation to refer to in every session.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw the three bands together and fill them with the client''s own words and body signs. The map earns its place when it becomes a shorthand: the client can say they are near the top edge and you both know what that means. Revisit and widen it as skills build; it is a picture of now, not a fixed trait.', '[{"id": "f0", "type": "textarea", "label": "Inside my window: how my body and thinking feel when I am okay"}, {"id": "f1", "type": "textarea", "label": "Above the window: signs I am revving up (body, thoughts, urges)"}, {"id": "f2", "type": "textarea", "label": "Below the window: signs I am shutting down (numb, foggy, far away)"}, {"id": "f3", "type": "textarea", "label": "What tends to push me above"}, {"id": "f4", "type": "textarea", "label": "What tends to drop me below"}, {"id": "f5", "type": "textarea", "label": "What brings me back down from above"}, {"id": "f6", "type": "textarea", "label": "What brings me back up from below"}]'::jsonb, array['PTSD and trauma', 'regulation', 'psychoeducation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('trigger-and-reminder-log', 'Trigger and Reminder Log', 'cbt'::resource_kind, 'A week of moments when something in the present set off the past, and what the client did next.', 'Help the client separate a reminder from the danger it points to, and see their own patterns.', array['Adults', 'Teens']::text[], 'One week', 'Frame it as noticing reminders, not reliving events; the log records the cue and the reaction, never the story of what happened. Review it together and look for the sensory reminders the client had not connected before. The final column is where planning happens for next week.', '[{"id": "f0", "type": "textarea", "label": "Date and where I was"}, {"id": "f1", "type": "textarea", "label": "What set it off (a sound, smell, place, phrase, body feeling)"}, {"id": "f2", "type": "textarea", "label": "What it reminded me of, in a few words only"}, {"id": "f3", "type": "textarea", "label": "How strong the reaction was (0-10) and how long it lasted"}, {"id": "f4", "type": "textarea", "label": "What I did in the moment"}, {"id": "f5", "type": "textarea", "label": "What helped, even a little"}, {"id": "f6", "type": "textarea", "label": "Was there real danger now? What I know about the present situation"}]'::jsonb, array['PTSD and trauma', 'triggers', 'monitoring']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('safe-place-imagery-script', 'Safe Place Imagery Script', 'worksheet'::resource_kind, 'A written, sensory-rich description of a place, real or imagined, where the client feels calm and in charge.', 'Give the client a rehearsed inner place to go to at the end of hard sessions and in hard nights.', array['Adults', 'Teens', 'Children']::text[], '20 minutes', 'Let the client choose the place and check it for hidden reminders before committing to it; a childhood bedroom is often not as safe as it sounds. Build it sense by sense and record the client reading it in their own voice if they want. Use it to close sessions rather than as an exposure exercise.', '[{"id": "f0", "type": "textarea", "label": "My place, and why I chose it"}, {"id": "f1", "type": "textarea", "label": "What I see there, near and far"}, {"id": "f2", "type": "textarea", "label": "What I hear"}, {"id": "f3", "type": "textarea", "label": "What I feel on my skin, and the temperature"}, {"id": "f4", "type": "textarea", "label": "What I smell"}, {"id": "f5", "type": "textarea", "label": "Who, if anyone, is with me"}, {"id": "f6", "type": "textarea", "label": "The words or image that get me there fastest"}]'::jsonb, array['PTSD and trauma', 'imagery', 'self-soothing']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('container-exercise', 'Container Exercise', 'worksheet'::resource_kind, 'An imagined container with a lid where the client puts material that is too much to carry between sessions.', 'Help the client set things down deliberately at the end of a session instead of carrying them out the door.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client design the container in detail: what it is made of, how it locks, where it lives. The rule is that what goes in comes back out in session, with you, which is what makes putting it away feel possible. Practice it with something small first so the client trusts the lid before it is needed.', '[{"id": "f0", "type": "textarea", "label": "My container: what it is made of and what the lid looks like"}, {"id": "f1", "type": "textarea", "label": "Where it is kept"}, {"id": "f2", "type": "textarea", "label": "How I close it (the words or gesture)"}, {"id": "f3", "type": "textarea", "label": "What I am putting in it today"}, {"id": "f4", "type": "textarea", "label": "When we will take it out together"}, {"id": "f5", "type": "textarea", "label": "What I will do in the ten minutes after closing it"}]'::jsonb, array['PTSD and trauma', 'containment', 'session structure']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('anxiety-body-map', 'Anxiety Body Map', 'worksheet'::resource_kind, 'An outline of a body where the client marks where anxiety lives and what it does there.', 'Turn a vague sense of dread into specific sensations the client can name and watch.', array['Adults', 'Teens', 'Children']::text[], '15 minutes', 'Draw a simple outline and color it in together; many clients discover they have been calling three different sensations by one name. Ask what each area does first when anxiety starts, because the earliest sign is the most useful one. Return to the map when teaching any body-based skill.', '[{"id": "f0", "type": "textarea", "label": "Where anxiety shows up first in my body"}, {"id": "f1", "type": "textarea", "label": "Where it goes next"}, {"id": "f2", "type": "textarea", "label": "What each spot feels like (tight, hot, fluttery, heavy)"}, {"id": "f3", "type": "textarea", "label": "The sensation I find hardest"}, {"id": "f4", "type": "textarea", "label": "What I usually do when I notice it"}, {"id": "f5", "type": "textarea", "label": "One thing I could try instead at the first spot"}]'::jsonb, array['anxiety', 'body awareness', 'interoception']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('uncertainty-experiments-sheet', 'Uncertainty Experiments Sheet', 'cbt'::resource_kind, 'Planned small acts of not checking, not asking and not planning, with predictions to test.', 'Loosen the belief that uncertainty itself is unbearable by practicing it in small steps.', array['Adults', 'Teens']::text[], 'One week', 'Start with experiments that feel about a three out of ten: sending a message without rereading it, ordering without researching the menu. The prediction column is where the learning is, so insist on a specific forecast before each one. Debrief what actually happened, not how it felt.', '[{"id": "f0", "type": "textarea", "label": "Ways I try to get certainty (checking, asking, over-planning, researching)"}, {"id": "f1", "type": "textarea", "label": "This week''s experiment: what I will not do"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen (be specific)"}, {"id": "f3", "type": "textarea", "label": "How sure I am (0-100%)"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "How the uncertainty felt at the start, and after an hour"}, {"id": "f6", "type": "textarea", "label": "What I learned about coping without knowing"}]'::jsonb, array['anxiety', 'uncertainty', 'behavioral experiment']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('avoidance-cost-ledger', 'Avoidance Cost Ledger', 'act'::resource_kind, 'A two-column account of what avoiding anxious situations has saved the client and what it has cost.', 'Make the long-term price of short-term relief visible without arguing with the fear.', array['Adults', 'Teens']::text[], '20 minutes', 'Validate the savings column fully; avoidance works, or nobody would do it. The costs usually appear when the client lists what they have stopped doing over years rather than weeks. Finish by asking which cost they would most like to stop paying, and let that point at the first approach step.', '[{"id": "f0", "type": "textarea", "label": "Situations I avoid because of anxiety"}, {"id": "f1", "type": "textarea", "label": "What avoiding each one saves me in the moment"}, {"id": "f2", "type": "textarea", "label": "What it has cost me over the last year"}, {"id": "f3", "type": "textarea", "label": "What I have stopped doing altogether"}, {"id": "f4", "type": "textarea", "label": "Which cost I most want to stop paying"}, {"id": "f5", "type": "textarea", "label": "What a first step back toward it would be"}]'::jsonb, array['anxiety', 'avoidance', 'values']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('anxiety-wave-timeline', 'Anxiety Wave Timeline', 'act'::resource_kind, 'A graph of one anxious episode from first flicker to fade, drawn from memory.', 'Show the client that anxiety peaks and passes on its own, and where their responses changed its shape.', array['Adults', 'Teens']::text[], '15 minutes', 'Draw the curve together on a timeline with real minutes on it. Most clients have never watched an episode through to the end because they left or distracted at the peak, so mark on the graph where that happened. Repeat with a later episode to show the wave getting shorter.', '[{"id": "f0", "type": "textarea", "label": "The episode I am drawing (when and where)"}, {"id": "f1", "type": "textarea", "label": "First flicker: what I noticed, and the time"}, {"id": "f2", "type": "textarea", "label": "Peak: how high (0-10) and when"}, {"id": "f3", "type": "textarea", "label": "What I did at the peak"}, {"id": "f4", "type": "textarea", "label": "When it started to fade, and what was happening then"}, {"id": "f5", "type": "textarea", "label": "How long the whole wave lasted"}, {"id": "f6", "type": "textarea", "label": "What I would do differently at the peak next time"}]'::jsonb, array['anxiety', 'acceptance', 'willingness']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('paced-breathing-practice-log', 'Paced Breathing Practice Log', 'dbt'::resource_kind, 'A daily record of slow, extended-exhale breathing, practiced when calm so it is there when needed.', 'Build a breathing habit that lowers the baseline rather than a rescue used only in emergencies.', array['Adults', 'Teens', 'Children']::text[], 'Five minutes daily for two weeks', 'Teach the pattern in session with a longer out-breath than in-breath, and check that the client is not gulping or straining. The log matters because most clients try breathing once during a spike, find it useless, and give up; practiced twice a day for two weeks it becomes usable. Note the before-and-after ratings, not just the practice.', '[{"id": "f0", "type": "textarea", "label": "Date and time"}, {"id": "f1", "type": "textarea", "label": "The pattern I used (for example in for 4, out for 6)"}, {"id": "f2", "type": "textarea", "label": "Minutes practiced"}, {"id": "f3", "type": "textarea", "label": "Tension before (0-10)"}, {"id": "f4", "type": "textarea", "label": "Tension after (0-10)"}, {"id": "f5", "type": "textarea", "label": "Anything that made it hard today"}, {"id": "f6", "type": "textarea", "label": "A moment I used it outside practice"}]'::jsonb, array['anxiety', 'breathing', 'regulation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('values-based-activity-menu', 'Values-Based Activity Menu', 'act'::resource_kind, 'A menu of small activities sorted by the value each one serves, to choose from on low days.', 'Give a client with no motivation a list they built while they had some.', array['Adults', 'Teens']::text[], '25 minutes', 'Build it on a better day, because on a flat day the client will not generate options. Sort by value rather than by pleasure, since pleasure is often absent and doing something that matters can come first. Keep every item under twenty minutes and include a few that take two.', '[{"id": "f0", "type": "textarea", "label": "Values that matter to me (connection, health, learning, creating, helping, order)"}, {"id": "f1", "type": "textarea", "label": "Two-minute activities that serve each value"}, {"id": "f2", "type": "textarea", "label": "Twenty-minute activities that serve each value"}, {"id": "f3", "type": "textarea", "label": "The one I will do tomorrow, and when"}, {"id": "f4", "type": "textarea", "label": "What might get in the way"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself when I do not feel like it"}]'::jsonb, array['depression', 'values', 'behavioral activation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('rumination-interruption-plan', 'Rumination Interruption Plan', 'cbt'::resource_kind, 'Identifies the client''s rumination triggers and plans a concrete switch away from the loop.', 'Shorten the time spent going over and over the same ground.', array['Adults', 'Teens']::text[], '20 minutes', 'Help the client tell rumination from useful reflection with one question: is this getting anywhere? The switch has to be physical and specific, because a vague plan to think about something else does not survive contact with the loop. Track the triggers for a week before choosing the switch.', '[{"id": "f0", "type": "textarea", "label": "Where and when I tend to ruminate (bed, commute, shower, scrolling)"}, {"id": "f1", "type": "textarea", "label": "The questions that loop (why me, what if, what did I do wrong)"}, {"id": "f2", "type": "textarea", "label": "How I feel after an hour of it"}, {"id": "f3", "type": "textarea", "label": "The question I will ask to catch it: is this getting anywhere?"}, {"id": "f4", "type": "textarea", "label": "My switch: the specific physical thing I will do instead"}, {"id": "f5", "type": "textarea", "label": "Where I will put a reminder"}, {"id": "f6", "type": "textarea", "label": "How it went this week"}]'::jsonb, array['depression', 'rumination', 'thinking traps']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('small-wins-ledger', 'Small Wins Ledger', 'worksheet'::resource_kind, 'A daily record of things done, however small, to counter the mind''s report that nothing happened.', 'Rebuild a sense of capability one entry at a time.', array['Adults', 'Teens']::text[], 'Two minutes daily', 'Set the bar deliberately low and say so: getting up, replying to one message, showering count. The point is evidence against the global verdict that the day was wasted. Read the week''s ledger aloud in session; clients often do not believe their own list until they hear it.', '[{"id": "f0", "type": "textarea", "label": "Date"}, {"id": "f1", "type": "textarea", "label": "Three things I did today, however small"}, {"id": "f2", "type": "textarea", "label": "One thing that was harder than it looked"}, {"id": "f3", "type": "textarea", "label": "Something I did for someone else, or let someone do for me"}, {"id": "f4", "type": "textarea", "label": "How I would rate today if I only looked at this list (0-10)"}, {"id": "f5", "type": "textarea", "label": "How I was rating it before I wrote it"}]'::jsonb, array['depression', 'self-esteem', 'monitoring']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('pleasant-events-bingo', 'Pleasant Events Bingo', 'game'::resource_kind, 'A bingo card of small pleasant activities, marked off through the week for a line or a full house.', 'Make activity scheduling feel like a game the client can win rather than homework they can fail.', array['Teens', 'Adults', 'Groups']::text[], '10 minutes to make, then one week', 'Fill the card with the client''s own items and a few gentle stretches, with a free square in the middle. A line is a win; a full house is not the goal. In groups, compare cards and trade ideas. The debrief asks which squares turned out better than expected, since anticipation is usually the part that is broken.', '[{"id": "f0", "type": "textarea", "label": "Squares on my card"}, {"id": "f1", "type": "textarea", "label": "The squares I marked this week"}, {"id": "f2", "type": "textarea", "label": "The one that turned out better than I expected"}, {"id": "f3", "type": "textarea", "label": "The one I could not face, and what got in the way"}, {"id": "f4", "type": "textarea", "label": "What I want on next week''s card"}]'::jsonb, array['depression', 'behavioral activation', 'play']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('mood-and-energy-rhythm-chart', 'Mood and Energy Rhythm Chart', 'worksheet'::resource_kind, 'A week of mood and energy rated at four points a day, to find the client''s better hours.', 'Find the times of day when action is most possible and schedule what matters there.', array['Adults', 'Teens']::text[], 'One week', 'Most clients assume the whole day is flat; the chart usually shows a window, often late morning or early evening. Rate mood and energy separately, since they diverge. Use the pattern to move the hardest tasks into the better hours and to plan rest for the worst ones instead of fighting them.', '[{"id": "f0", "type": "textarea", "label": "Date"}, {"id": "f1", "type": "textarea", "label": "Morning: mood (0-10) and energy (0-10)"}, {"id": "f2", "type": "textarea", "label": "Midday: mood and energy"}, {"id": "f3", "type": "textarea", "label": "Late afternoon: mood and energy"}, {"id": "f4", "type": "textarea", "label": "Evening: mood and energy"}, {"id": "f5", "type": "textarea", "label": "What I did in my best window"}, {"id": "f6", "type": "textarea", "label": "What I will move into that window next week"}]'::jsonb, array['depression', 'monitoring', 'scheduling']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('task-breakdown-ladder', 'Task Breakdown Ladder', 'worksheet'::resource_kind, 'Splits one stuck task into steps so small the first one takes under five minutes.', 'Get a client past the wall of a task that has no obvious first move.', array['Adults', 'Teens']::text[], '15 minutes', 'Do the breaking-down together in session, since that step is exactly what the client finds hard. Steps should be physical actions, not goals: open the folder, not organize the folder. Have the client do the first rung before leaving the room. Photograph the ladder so it lives on the phone.', '[{"id": "f0", "type": "textarea", "label": "The task I am stuck on"}, {"id": "f1", "type": "textarea", "label": "Why it feels impossible right now"}, {"id": "f2", "type": "textarea", "label": "Rungs: every step in order, each under five minutes"}, {"id": "f3", "type": "textarea", "label": "The first rung, done now"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this ladder"}, {"id": "f5", "type": "textarea", "label": "What I will do when I finish a rung (a tick, a break, a message)"}, {"id": "f6", "type": "textarea", "label": "When I will do rung two"}]'::jsonb, array['ADHD', 'task initiation', 'executive function']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('time-estimate-log', 'Time Estimate Log', 'cbt'::resource_kind, 'A log of how long the client guessed tasks would take against how long they actually took.', 'Calibrate the client''s sense of time with their own data instead of with reproach.', array['Adults', 'Teens']::text[], 'One week', 'Keep the tone curious; the point is a personal correction factor, not proof of failure. Most clients find they underestimate boring tasks and overestimate dreaded ones. Use the ratio to pad plans and to argue with the belief that there is plenty of time.', '[{"id": "f0", "type": "textarea", "label": "Task"}, {"id": "f1", "type": "textarea", "label": "My guess before starting"}, {"id": "f2", "type": "textarea", "label": "Actual time (use a timer)"}, {"id": "f3", "type": "textarea", "label": "The ratio: actual divided by guess"}, {"id": "f4", "type": "textarea", "label": "What I did not count (finding things, getting started, interruptions)"}, {"id": "f5", "type": "textarea", "label": "My correction factor for next week''s plans"}]'::jsonb, array['ADHD', 'time management', 'self-monitoring']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-doubling-plan', 'Body Doubling Plan', 'worksheet'::resource_kind, 'A plan for working alongside another person, in the room or on a call, to get hard tasks started.', 'Use the presence of another person as external structure for tasks that will not start alone.', array['Adults', 'Teens']::text[], '15 minutes', 'Explain that the double does not help or supervise; they just work nearby. Help the client list who could do this and how to ask without it sounding like babysitting. Plan the first session with a fixed start and stop time and a task chosen in advance, since deciding what to do is itself a stuck point.', '[{"id": "f0", "type": "textarea", "label": "Tasks I cannot seem to start alone"}, {"id": "f1", "type": "textarea", "label": "People who could sit with me (in person or on a call)"}, {"id": "f2", "type": "textarea", "label": "How I will ask them"}, {"id": "f3", "type": "textarea", "label": "Our first session: when, how long, and what I will work on"}, {"id": "f4", "type": "textarea", "label": "What the double will and will not do"}, {"id": "f5", "type": "textarea", "label": "How it went, and what I got done"}]'::jsonb, array['ADHD', 'task initiation', 'support']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('launch-pad-setup', 'Launch Pad Setup', 'kids'::resource_kind, 'A fixed spot by the door where everything for tomorrow lives, set up with the child each evening.', 'Take the morning scramble out of the family''s day with one predictable place for everything.', array['Children', 'Teens']::text[], '20 minutes to set up, then nightly', 'Let the child choose the spot and decorate a checklist for it. The parent''s job is the evening check-in, not the morning rescue; agree a script for when something is missing that does not turn into a lecture. Review after a week and shrink the checklist to what the child actually forgets.', '[{"id": "f0", "type": "textarea", "label": "Where my launch pad is"}, {"id": "f1", "type": "textarea", "label": "What goes on it every night (bag, shoes, forms, water bottle, gear)"}, {"id": "f2", "type": "textarea", "label": "What goes on it only on some days"}, {"id": "f3", "type": "textarea", "label": "When we check it together each evening"}, {"id": "f4", "type": "textarea", "label": "What my grown-up says if something is missing"}, {"id": "f5", "type": "textarea", "label": "How many smooth mornings we had this week"}]'::jsonb, array['ADHD', 'routines', 'children', 'parenting']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('beat-the-timer-sprint', 'Beat the Timer Sprint', 'game'::resource_kind, 'A short, timed race against a visible clock to start and finish one small task.', 'Make starting feel like a game with a finish line instead of an open-ended chore.', array['Children', 'Teens', 'Adults']::text[], '10 minutes', 'Use a visible timer the child can see counting down, set for less time than the task should take so there is real tension. Play it first with something trivial in session so the rules are learned while the stakes are low. Winning is starting and finishing, not speed; a personal best chart keeps it going at home.', '[{"id": "f0", "type": "textarea", "label": "The task for this sprint"}, {"id": "f1", "type": "textarea", "label": "The timer I set"}, {"id": "f2", "type": "textarea", "label": "Did I beat it? By how much"}, {"id": "f3", "type": "textarea", "label": "My personal best on this task"}, {"id": "f4", "type": "textarea", "label": "What made it fun, and what made it stressful"}, {"id": "f5", "type": "textarea", "label": "The next task I want to sprint"}]'::jsonb, array['ADHD', 'play', 'task initiation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('triggers-urges-alternatives-log', 'Triggers, Urges and Alternatives Log', 'cbt'::resource_kind, 'A daily log of what set off an urge, how strong it got, and what the client did instead.', 'Show the client their own urge pattern and build a list of alternatives that have actually worked.', array['Adults', 'Teens']::text[], 'One week', 'Keep it about substance use or the behavior in plain words the client chooses. The strength column shows that urges peak and pass, and the alternatives column becomes a personal menu. Review it without judgment about the days that went badly; the log is data either way.', '[{"id": "f0", "type": "textarea", "label": "Date and time"}, {"id": "f1", "type": "textarea", "label": "What was happening just before (place, people, feeling, time of day)"}, {"id": "f2", "type": "textarea", "label": "The urge, and how strong (0-10)"}, {"id": "f3", "type": "textarea", "label": "How long it stayed strong"}, {"id": "f4", "type": "textarea", "label": "What I did"}, {"id": "f5", "type": "textarea", "label": "If I used, what happened next; if I did not, what I did instead"}, {"id": "f6", "type": "textarea", "label": "One alternative I want ready for next time"}]'::jsonb, array['addiction', 'urges', 'triggers', 'monitoring']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('urge-surfing-script', 'Urge Surfing Script', 'act'::resource_kind, 'A short guided practice for riding an urge like a wave rather than fighting it or giving in.', 'Teach the client that an urge is a rising and falling sensation that can be watched.', array['Adults', 'Teens']::text[], '10 minutes to teach, then in the moment', 'Read it aloud in session while the client recalls a recent urge at low intensity, and narrate the body sensations as they change. The words matter less than the discovery that the urge changed while they watched. Pair with the log so the client can see how long waves really last.', '[{"id": "f0", "type": "textarea", "label": "Where I feel the urge in my body right now"}, {"id": "f1", "type": "textarea", "label": "What it is doing: growing, steady, shifting"}, {"id": "f2", "type": "textarea", "label": "The words I use to describe it without judging it"}, {"id": "f3", "type": "textarea", "label": "How I breathe while I watch it"}, {"id": "f4", "type": "textarea", "label": "What happened to it after two minutes"}, {"id": "f5", "type": "textarea", "label": "What I noticed about myself while surfing"}]'::jsonb, array['addiction', 'urges', 'mindfulness']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('recovery-support-roster', 'Recovery Support Roster', 'worksheet'::resource_kind, 'A list of the people, places and times the client can lean on, with what each one is good for.', 'Make support concrete enough to use at eleven at night.', array['Adults', 'Teens']::text[], '20 minutes', 'Sort people by what they are actually good for: company, honesty, a lift, a distraction, someone who has been there. Include groups, lines and places, not just friends. Check that at least two entries are reachable at the client''s hardest hour, and have them save the numbers before leaving.', '[{"id": "f0", "type": "textarea", "label": "People who know about my recovery, and what each is good for"}, {"id": "f1", "type": "textarea", "label": "People who do not know, but who are good company"}, {"id": "f2", "type": "textarea", "label": "Meetings, groups or places I can go"}, {"id": "f3", "type": "textarea", "label": "Numbers I will save today"}, {"id": "f4", "type": "textarea", "label": "My hardest hour, and who is reachable then"}, {"id": "f5", "type": "textarea", "label": "Who I will tell about a rough patch before it becomes a lapse"}]'::jsonb, array['addiction', 'support', 'relapse prevention']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('playing-the-tape-forward', 'Playing the Tape Forward', 'cbt'::resource_kind, 'Walks a single urge through to the next morning, so the whole story is present at the moment of choice.', 'Counter the mind''s edit that stops at the first good part.', array['Adults', 'Teens']::text[], '15 minutes', 'Do it out loud, scene by scene, and let the client tell it; the details they add are the ones that will stick. Then write a one-line version for the phone. It works best for a specific plan, not a general resolve, and it pairs with the log''s alternatives column.', '[{"id": "f0", "type": "textarea", "label": "The urge, and what my mind shows me first"}, {"id": "f1", "type": "textarea", "label": "Play it forward: the next hour"}, {"id": "f2", "type": "textarea", "label": "That night"}, {"id": "f3", "type": "textarea", "label": "The next morning"}, {"id": "f4", "type": "textarea", "label": "The days after"}, {"id": "f5", "type": "textarea", "label": "The one-line version I will keep on my phone"}]'::jsonb, array['addiction', 'urges', 'decisions']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('lapse-learning-sheet', 'Lapse Learning Sheet', 'worksheet'::resource_kind, 'A structured look back at a slip: what led up to it, what it meant, and what changes now.', 'Turn a lapse into information instead of a verdict on the whole attempt.', array['Adults', 'Teens']::text[], '25 minutes', 'Complete it in session soon after the lapse, while the details are available and before shame has rewritten it. The distinction between a lapse and giving up is the heart of it; write that distinction in the client''s own words. End with changes to the plan, not promises.', '[{"id": "f0", "type": "textarea", "label": "What happened, briefly"}, {"id": "f1", "type": "textarea", "label": "The hours before: where I was, who with, how I felt"}, {"id": "f2", "type": "textarea", "label": "The first small decision that led toward it"}, {"id": "f3", "type": "textarea", "label": "What I told myself right before"}, {"id": "f4", "type": "textarea", "label": "What I am telling myself now"}, {"id": "f5", "type": "textarea", "label": "What this does not mean about me or my recovery"}, {"id": "f6", "type": "textarea", "label": "What changes in my plan this week"}]'::jsonb, array['addiction', 'relapse prevention', 'shame']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('time-out-agreement', 'Time-Out Agreement', 'couples'::resource_kind, 'A written agreement between partners for calling and returning from a pause during conflict.', 'Let either partner stop a fight before it does damage, without the pause becoming a punishment.', array['Couples']::text[], '25 minutes', 'The return time is the part that makes it work; a time-out with no return is stonewalling with a name. Agree on a word or gesture, a minimum and maximum length, what each partner does while apart, and how they come back. Rehearse the call and the return in session so the first real use is not the first attempt.', '[{"id": "f0", "type": "textarea", "label": "Our time-out word or signal"}, {"id": "f1", "type": "textarea", "label": "How long: minimum and maximum"}, {"id": "f2", "type": "textarea", "label": "What I will do during the pause (no rehearsing the argument)"}, {"id": "f3", "type": "textarea", "label": "What I will not do (drive angry, drink, text about it)"}, {"id": "f4", "type": "textarea", "label": "How we come back: the first sentence"}, {"id": "f5", "type": "textarea", "label": "What happens if one of us is not ready at the return time"}]'::jsonb, array['anger management', 'conflict', 'de-escalation', 'relationship issues']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('anger-rules-audit', 'Anger Rules Audit', 'cbt'::resource_kind, 'Lists the client''s unwritten rules for how people should behave, and what happens when someone breaks one.', 'Find the shoulds underneath the anger and decide which are worth the cost.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for the rules behind three recent flare-ups; they tend to be about respect, fairness and effort. Rate each rule for how often the world breaks it. The question is not whether the rule is right but whether holding it this tightly is worth what it costs the client.', '[{"id": "f0", "type": "textarea", "label": "A recent flare-up"}, {"id": "f1", "type": "textarea", "label": "The rule that was broken (people should...)"}, {"id": "f2", "type": "textarea", "label": "How often the world breaks this rule"}, {"id": "f3", "type": "textarea", "label": "What holding this rule costs me"}, {"id": "f4", "type": "textarea", "label": "A looser version I could live with"}, {"id": "f5", "type": "textarea", "label": "Where I will try the looser version this week"}]'::jsonb, array['anger management', 'core beliefs', 'thinking traps']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('cooling-kit-card', 'Cooling Kit Card', 'dbt'::resource_kind, 'A card of physical cooling steps to use in the first two minutes of rising anger.', 'Give the client something to do with the body before the mouth takes over.', array['Adults', 'Teens']::text[], '10 minutes to build, then in the moment', 'Choose steps that change physiology: cold water on the face, a long exhale, unclenching the hands, walking. Keep it to four or five so it can be read in a glance. Rehearse in session with a mildly annoying memory and note which step drops the number fastest.', '[{"id": "f0", "type": "textarea", "label": "Body signs that I am at a six out of ten"}, {"id": "f1", "type": "textarea", "label": "My four cooling steps, in order"}, {"id": "f2", "type": "textarea", "label": "The one that works fastest for me"}, {"id": "f3", "type": "textarea", "label": "Where this card lives"}, {"id": "f4", "type": "textarea", "label": "A time I used it this week, and the number before and after"}]'::jsonb, array['anger management', 'distress tolerance', 'regulation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('assertive-replay-sheet', 'Assertive Replay Sheet', 'worksheet'::resource_kind, 'Rewrites a recent angry exchange as the assertive version the client wishes they had said.', 'Build the middle path between exploding and swallowing it.', array['Adults', 'Teens']::text[], '20 minutes', 'Take a real exchange, write what was actually said, then draft the assertive version: the observation, the feeling, the request. Read both aloud and ask which one would have got the client what they wanted. Role-play the assertive line with pushback so it survives a second round.', '[{"id": "f0", "type": "textarea", "label": "What happened, and what I said"}, {"id": "f1", "type": "textarea", "label": "What I actually wanted"}, {"id": "f2", "type": "textarea", "label": "The observation, without blame"}, {"id": "f3", "type": "textarea", "label": "The feeling, in one word"}, {"id": "f4", "type": "textarea", "label": "The request, specific and doable"}, {"id": "f5", "type": "textarea", "label": "How I expect them to respond, and my calm reply to that"}]'::jsonb, array['anger management', 'assertiveness', 'communication']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('anger-iceberg-drawing', 'Anger Iceberg Drawing', 'kids'::resource_kind, 'A drawn iceberg with anger above the waterline and the feelings underneath it below.', 'Help a child find the hurt, fear or embarrassment that anger is standing in front of.', array['Children', 'Teens']::text[], '20 minutes', 'Draw the iceberg large and let the child fill the underwater part with feeling words or faces. Use a recent blow-up as the example. Parents can complete one about themselves alongside, which normalizes it and often opens something. Keep the drawing and add to it over sessions.', '[{"id": "f0", "type": "textarea", "label": "Above the water: what my anger looks like from outside"}, {"id": "f1", "type": "textarea", "label": "A time I got really angry"}, {"id": "f2", "type": "textarea", "label": "Under the water: what else I was feeling"}, {"id": "f3", "type": "textarea", "label": "Which under-water feeling was biggest"}, {"id": "f4", "type": "textarea", "label": "What I needed right then"}, {"id": "f5", "type": "textarea", "label": "What a grown-up could do when they see my tip of the iceberg"}]'::jsonb, array['anger management', 'children', 'emotion identification']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('obsession-compulsion-cycle-map', 'Obsession-Compulsion Cycle Map', 'cbt'::resource_kind, 'A drawn loop from intrusive thought to anxiety to ritual to relief and back again.', 'Give the client a picture of how the ritual keeps the thought coming back.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw it as a circle and let the client supply each stage from a recent example. The relief arrow is the one to linger on: it is the reason the loop persists. Include mental rituals and reassurance seeking, which clients often do not count. Refer back to the map whenever a new ritual comes to light.', '[{"id": "f0", "type": "textarea", "label": "The thought or image that shows up"}, {"id": "f1", "type": "textarea", "label": "What it makes me feel, and how strong (0-10)"}, {"id": "f2", "type": "textarea", "label": "What I do to make it go away (including in my head)"}, {"id": "f3", "type": "textarea", "label": "How much relief I get, and for how long"}, {"id": "f4", "type": "textarea", "label": "How soon the thought comes back"}, {"id": "f5", "type": "textarea", "label": "Where on the loop I could try doing something different"}]'::jsonb, array['OCD', 'formulation', 'maintenance cycle']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('ritual-delay-log', 'Ritual Delay Log', 'cbt'::resource_kind, 'A record of rituals postponed by a chosen number of minutes, and what happened to the urge meanwhile.', 'Introduce the idea of not doing the ritual through delay rather than outright refusal.', array['Adults', 'Teens']::text[], 'One week', 'Delay is easier to agree to than stopping and teaches the same lesson. Start with delays of a few minutes on a low-intensity ritual and lengthen them as the client sees the urge drop. Keep the client honest about mental rituals during the delay, since those quietly replace the visible one.', '[{"id": "f0", "type": "textarea", "label": "The ritual"}, {"id": "f1", "type": "textarea", "label": "The urge when it started (0-10)"}, {"id": "f2", "type": "textarea", "label": "How long I delayed"}, {"id": "f3", "type": "textarea", "label": "What I did during the delay (no mental rituals)"}, {"id": "f4", "type": "textarea", "label": "The urge at the end of the delay (0-10)"}, {"id": "f5", "type": "textarea", "label": "Did I do the ritual after? What happened either way"}, {"id": "f6", "type": "textarea", "label": "Next delay I will try"}]'::jsonb, array['OCD', 'exposure', 'response prevention']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('living-with-maybe-practice', 'Living With Maybe Practice', 'act'::resource_kind, 'Short scripted statements that accept uncertainty about a feared outcome instead of neutralizing it.', 'Help the client sit with maybe rather than chasing certainty through rituals.', array['Adults', 'Teens']::text[], '15 minutes', 'Write the statements in the client''s own words and make sure none of them is a reassurance in disguise; the point is not that it will probably be fine but that they can live without knowing. Practice saying them aloud in session and then use them in place of a ritual, paired with the delay log.', '[{"id": "f0", "type": "textarea", "label": "The thing I keep needing to be sure about"}, {"id": "f1", "type": "textarea", "label": "How I usually get certainty"}, {"id": "f2", "type": "textarea", "label": "My maybe statement: maybe it will, maybe it will not, and I can..."}, {"id": "f3", "type": "textarea", "label": "What I feel when I say it"}, {"id": "f4", "type": "textarea", "label": "When I used it this week instead of a ritual"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the uncertainty over the day"}]'::jsonb, array['OCD', 'acceptance', 'uncertainty']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('family-accommodation-log', 'Family Accommodation Log', 'worksheet'::resource_kind, 'A family''s record of the ways they take part in rituals, answer for reassurance, or arrange life around the fears.', 'Show a family how much of the household has bent around OCD, and plan what to step back from first.', array['Adults', 'Teens']::text[], 'One week', 'Best completed by the family member, with the client''s agreement, and reviewed together. Accommodation is done out of love, so name that before listing it. Choose one small accommodation to withdraw first, agree the exact words the family member will use instead, and expect a harder week before an easier one.', '[{"id": "f0", "type": "textarea", "label": "Things I do because of the fears (checking for them, answering questions, avoiding places)"}, {"id": "f1", "type": "textarea", "label": "Rituals I take part in"}, {"id": "f2", "type": "textarea", "label": "How many times a day I am asked for reassurance"}, {"id": "f3", "type": "textarea", "label": "What happens when I refuse"}, {"id": "f4", "type": "textarea", "label": "The one accommodation we will withdraw first"}, {"id": "f5", "type": "textarea", "label": "What I will say instead, in the words we agreed"}, {"id": "f6", "type": "textarea", "label": "How the week went"}]'::jsonb, array['OCD', 'family', 'accommodation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('bossy-brain-talk-back', 'Bossy Brain Talk-Back', 'kids'::resource_kind, 'A child names the part of their brain that gives worry orders and practices talking back to it.', 'Externalize the intrusive thoughts and rituals so the child and family are on the same side against them.', array['Children']::text[], '25 minutes', 'Let the child choose the name and draw the character; the sillier the better. Coach parents to use the same name at home so the child is never the problem. Talk-back lines should be short and defiant, and rehearsed in session with you playing the bossy brain giving orders.', '[{"id": "f0", "type": "textarea", "label": "My bossy brain''s name and what it looks like"}, {"id": "f1", "type": "textarea", "label": "The orders it gives me"}, {"id": "f2", "type": "textarea", "label": "What happens when I obey"}, {"id": "f3", "type": "textarea", "label": "My talk-back lines"}, {"id": "f4", "type": "textarea", "label": "A time this week I talked back"}, {"id": "f5", "type": "textarea", "label": "What my family says to help me boss it back"}]'::jsonb, array['OCD', 'children', 'externalizing']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('panic-timeline-sheet', 'Panic Timeline Sheet', 'cbt'::resource_kind, 'A minute-by-minute account of one panic episode: sensation, thought, action, and what happened next.', 'Slow a panic episode down enough to see the order of events and where a thought made it worse.', array['Adults', 'Teens']::text[], '20 minutes', 'Reconstruct the most recent episode in session, starting a few minutes before the client noticed anything. Most clients discover a sensation came first and the catastrophic thought second, which is the foundation for everything that follows. Note what they did to escape and what that taught them.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was doing just before"}, {"id": "f1", "type": "textarea", "label": "The first sensation I noticed"}, {"id": "f2", "type": "textarea", "label": "The first thought about that sensation"}, {"id": "f3", "type": "textarea", "label": "What happened in my body next"}, {"id": "f4", "type": "textarea", "label": "What I did (sat down, left, called someone, held on)"}, {"id": "f5", "type": "textarea", "label": "How long until it faded"}, {"id": "f6", "type": "textarea", "label": "What I concluded afterward about my body or the place"}]'::jsonb, array['panic attacks', 'formulation', 'maintenance cycle']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-sensation-practice-log', 'Body Sensation Practice Log', 'cbt'::resource_kind, 'A record of deliberately bringing on mild panic-like sensations in safe conditions and letting them pass.', 'Let the client learn from experience that the sensations themselves are uncomfortable but not dangerous.', array['Adults', 'Teens']::text[], 'One week', 'Choose the exercises in session with the client''s medical situation in mind, and demonstrate each one yourself first: spinning in a chair, breathing through a straw, running on the spot. Rate the sensation and the fear separately. Repetition is the point, so five short practices beat one long one.', '[{"id": "f0", "type": "textarea", "label": "The exercise and how long I did it"}, {"id": "f1", "type": "textarea", "label": "The sensations it produced"}, {"id": "f2", "type": "textarea", "label": "How similar to panic (0-10)"}, {"id": "f3", "type": "textarea", "label": "How frightening (0-10)"}, {"id": "f4", "type": "textarea", "label": "What I did while it faded (no escaping, no safety moves)"}, {"id": "f5", "type": "textarea", "label": "How long until it faded"}, {"id": "f6", "type": "textarea", "label": "What I learned this time"}]'::jsonb, array['panic attacks', 'interoception', 'exposure']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('first-sixty-seconds-card', 'First Sixty Seconds Card', 'dbt'::resource_kind, 'A pocket card with the client''s plan for the first minute of a panic surge.', 'Replace the scramble to escape with a rehearsed sequence the client can do anywhere.', array['Adults', 'Teens']::text[], '10 minutes to build, then in the moment', 'Keep it to three or four moves that do not involve leaving or checking: feet on the floor, a long exhale, name the sensation, let it crest. Rehearse the sequence in session during a sensation exercise so it is attached to a real feeling. The card is a memory aid, not a safety behavior; retire it once the sequence is automatic.', '[{"id": "f0", "type": "textarea", "label": "The first sign a surge is starting"}, {"id": "f1", "type": "textarea", "label": "Move one"}, {"id": "f2", "type": "textarea", "label": "Move two"}, {"id": "f3", "type": "textarea", "label": "Move three"}, {"id": "f4", "type": "textarea", "label": "What I say to myself as it crests"}, {"id": "f5", "type": "textarea", "label": "What I will not do (leave, sit down in the aisle, phone for reassurance)"}, {"id": "f6", "type": "textarea", "label": "Where this card lives"}]'::jsonb, array['panic attacks', 'distress tolerance', 'grounding']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('sensation-meaning-sheet', 'Sensation Meaning Sheet', 'cbt'::resource_kind, 'Pairs each feared body sensation with the client''s frightening explanation and a plainer one.', 'Weaken the link between a sensation and the catastrophe the client attaches to it.', array['Adults', 'Teens']::text[], '20 minutes', 'List the sensations first, then the meanings the client gives them: a racing heart means a heart attack, dizziness means fainting. Supply plain physiology for the alternative column and check the client actually believes it; if not, that is the next sensation exercise. Rate belief in both columns and repeat over weeks.', '[{"id": "f0", "type": "textarea", "label": "The sensation"}, {"id": "f1", "type": "textarea", "label": "What I fear it means, and how much I believe that (0-100%)"}, {"id": "f2", "type": "textarea", "label": "What else it could mean"}, {"id": "f3", "type": "textarea", "label": "Evidence from my own history (how many times, what happened)"}, {"id": "f4", "type": "textarea", "label": "How much I believe the plainer meaning (0-100%)"}, {"id": "f5", "type": "textarea", "label": "The sensation I most want to test next"}]'::jsonb, array['panic attacks', 'thinking traps', 'belief change']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('panic-support-plan-for-partners', 'Panic Support Plan for Partners', 'couples'::resource_kind, 'Agreed roles for a partner or family member during and after a panic episode.', 'Turn a well-meaning helper from a safety net into a support for facing the episode.', array['Couples', 'Adults']::text[], '25 minutes', 'Partners usually help by escaping together, which keeps the fear alive. Agree in session what the partner will and will not do: stay near, speak little, not leave with the client, not ask if they are okay every thirty seconds. Write the partner''s script in their words and rehearse it with both present.', '[{"id": "f0", "type": "textarea", "label": "What my partner currently does when I panic"}, {"id": "f1", "type": "textarea", "label": "What helps in the moment, and what quietly makes it worse"}, {"id": "f2", "type": "textarea", "label": "What I want them to do"}, {"id": "f3", "type": "textarea", "label": "What I want them not to do"}, {"id": "f4", "type": "textarea", "label": "The words they will use"}, {"id": "f5", "type": "textarea", "label": "What we will do together afterward"}, {"id": "f6", "type": "textarea", "label": "How we will review this after the next episode"}]'::jsonb, array['panic attacks', 'support', 'relationship issues']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('repair-after-yelling-sheet', 'Repair After Yelling Sheet', 'worksheet'::resource_kind, 'A short script for a parent to reconnect with a child after losing their temper.', 'Make repair the expected next step after a rupture, so a bad moment does not become a bad week.', array['Adults']::text[], '15 minutes', 'Normalize the yelling before planning the repair; a parent drowning in guilt cannot learn. The repair is short, owns the parent''s part without self-punishment, and does not extract a promise from the child. Rehearse it in session, then have the parent log one real repair.', '[{"id": "f0", "type": "textarea", "label": "What happened, briefly"}, {"id": "f1", "type": "textarea", "label": "What I was feeling and needing at the time"}, {"id": "f2", "type": "textarea", "label": "The repair I will say (in my own words, about a minute long)"}, {"id": "f3", "type": "textarea", "label": "What I will not do (over-apologize, explain at length, blame the child''s behavior)"}, {"id": "f4", "type": "textarea", "label": "When I will do it"}, {"id": "f5", "type": "textarea", "label": "How my child responded"}, {"id": "f6", "type": "textarea", "label": "What I will do differently at the first sign next time"}]'::jsonb, array['parenting', 'repair', 'emotion regulation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('house-rules-builder', 'House Rules Builder', 'kids'::resource_kind, 'A family writes a small set of house rules together, with what happens when they are followed and when they are not.', 'Make the rules few, positive, visible and agreed, so they can be pointed to instead of argued about.', array['Children', 'Teens', 'Adults']::text[], '30 minutes', 'Keep it to three to five rules stated as what to do rather than what not to do. Children propose rules for the adults too, which builds buy-in and is usually fair. Consequences are small, quick and related to the rule. Post it somewhere visible and review in a month.', '[{"id": "f0", "type": "textarea", "label": "Our rules (three to five, said as what we do)"}, {"id": "f1", "type": "textarea", "label": "A rule the kids chose for the grown-ups"}, {"id": "f2", "type": "textarea", "label": "What happens when a rule is followed"}, {"id": "f3", "type": "textarea", "label": "What happens when a rule is broken"}, {"id": "f4", "type": "textarea", "label": "Where our rules are posted"}, {"id": "f5", "type": "textarea", "label": "The date we will review them"}]'::jsonb, array['parenting', 'children', 'behavioral', 'family']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('when-then-statement-planner', 'When-Then Statement Planner', 'worksheet'::resource_kind, 'Rewrites a parent''s common commands as when-then statements that make the order of events clear.', 'Reduce power struggles by stating the sequence instead of the threat.', array['Adults']::text[], '15 minutes', 'Take the parent''s three most repeated commands and rewrite each as when the required thing happens, then the wanted thing follows. The tone is matter-of-fact, said once, and then the parent waits. Rehearse the waiting, since that is the hard part.', '[{"id": "f0", "type": "textarea", "label": "Commands I repeat most"}, {"id": "f1", "type": "textarea", "label": "Each one as a when-then statement"}, {"id": "f2", "type": "textarea", "label": "How I will say it (tone, once, then wait)"}, {"id": "f3", "type": "textarea", "label": "What I will do while I wait"}, {"id": "f4", "type": "textarea", "label": "Which one I will use first this week"}, {"id": "f5", "type": "textarea", "label": "How it went"}]'::jsonb, array['parenting', 'communication', 'behavioral']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('parent-trigger-map', 'Parent Trigger Map', 'cbt'::resource_kind, 'Identifies the child behaviors and situations that get under a parent''s skin fastest, and why.', 'Help a parent see their own reactions coming so they can choose a response.', array['Adults']::text[], '20 minutes', 'Ask for the three moments that flip the parent fastest and follow each one to the belief underneath: disrespect, being ignored, feeling judged. Often it links to the parent''s own upbringing, and one or two sentences about that are enough. Plan a pause for the top trigger only.', '[{"id": "f0", "type": "textarea", "label": "The child behaviors that get to me fastest"}, {"id": "f1", "type": "textarea", "label": "What each one seems to mean about me or about my child"}, {"id": "f2", "type": "textarea", "label": "Where that meaning may come from in my own history"}, {"id": "f3", "type": "textarea", "label": "My body''s earliest warning sign"}, {"id": "f4", "type": "textarea", "label": "My pause for the top trigger"}, {"id": "f5", "type": "textarea", "label": "What I will say after the pause"}]'::jsonb, array['parenting', 'triggers', 'core beliefs']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('co-parent-handoff-plan', 'Co-Parent Handoff Plan', 'couples'::resource_kind, 'Agreed steps for handing a child between parents, whether across a house or across two homes.', 'Take the friction out of transitions so the child does not carry it.', array['Couples', 'Adults']::text[], '25 minutes', 'Works for couples together and for separated parents. Keep the plan about logistics and tone, not about the relationship: what is said at handoff, what is not, how information travels. The child''s view of a good handoff is worth asking about separately and including.', '[{"id": "f0", "type": "textarea", "label": "When and where handoffs happen"}, {"id": "f1", "type": "textarea", "label": "What we say to each other at handoff"}, {"id": "f2", "type": "textarea", "label": "What we do not raise at handoff"}, {"id": "f3", "type": "textarea", "label": "How information about the child travels between us"}, {"id": "f4", "type": "textarea", "label": "What our child says makes a handoff easier"}, {"id": "f5", "type": "textarea", "label": "Our signal when a handoff is going wrong"}, {"id": "f6", "type": "textarea", "label": "How we will review this in a month"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('sleep-and-support-rota', 'Sleep and Support Rota', 'worksheet'::resource_kind, 'A week''s plan for who covers the nights, who covers the mornings, and where a protected block of sleep sits.', 'Get a new parent one stretch of protected sleep and make the support around them concrete.', array['Adults', 'Couples']::text[], '20 minutes', 'Sleep is the lever that moves most else in the early months, so plan it first. Involve the partner or another supporter in the room if possible. The protected block should be four or five hours, at the same time each night where feeding allows. Note who is on call for each slot and what counts as enough help.', '[{"id": "f0", "type": "textarea", "label": "My protected sleep block: when, and who covers"}, {"id": "f1", "type": "textarea", "label": "Night shifts this week"}, {"id": "f2", "type": "textarea", "label": "Morning cover this week"}, {"id": "f3", "type": "textarea", "label": "Others who could take a slot (family, friends, paid help)"}, {"id": "f4", "type": "textarea", "label": "What I need from a supporter beyond holding the baby"}, {"id": "f5", "type": "textarea", "label": "One thing I will stop doing to make room for sleep"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('intrusive-thoughts-after-birth-sheet', 'Intrusive Thoughts After Birth Sheet', 'cbt'::resource_kind, 'Names the unwanted thoughts that arrive with a new baby and separates having a thought from wanting it.', 'Reduce the shame and fear around intrusive thoughts so the parent can talk about them.', array['Adults']::text[], '20 minutes', 'Ask directly and normalize before the client answers; most new parents have had frightening thoughts and told no one. Distinguish a thought the parent finds horrifying from an intention, and say plainly that horror is a sign of care. Anything the parent describes as a plan or wish needs safety planning in session. Include 988 in the prompts.', '[{"id": "f0", "type": "textarea", "label": "Thoughts that come that I do not want"}, {"id": "f1", "type": "textarea", "label": "What I feel when they come"}, {"id": "f2", "type": "textarea", "label": "What I do to make them stop"}, {"id": "f3", "type": "textarea", "label": "The difference between having a thought and wanting to act on it, in my words"}, {"id": "f4", "type": "textarea", "label": "Who I can tell about these"}, {"id": "f5", "type": "textarea", "label": "If things ever feel unsafe: 988 (call or text), and my other numbers"}]'::jsonb, array['perinatal and postpartum', 'intrusive thoughts', 'shame']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('new-parent-values-check', 'New Parent Values Check', 'act'::resource_kind, 'A short review of what kind of parent and person the client wants to be, against what the days actually hold.', 'Reconnect a depleted new parent with what matters, in a form that fits a five-minute window.', array['Adults']::text[], '15 minutes', 'Keep it small; a new parent has no bandwidth for a life review. Three values, three tiny actions. Watch for perfectionism about parenting and name it. The gap between values and days is meant to be noticed with kindness, not closed this week.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be, in three words"}, {"id": "f1", "type": "textarea", "label": "The kind of person I still want to be, in three words"}, {"id": "f2", "type": "textarea", "label": "What my days actually look like right now"}, {"id": "f3", "type": "textarea", "label": "One two-minute action for each value"}, {"id": "f4", "type": "textarea", "label": "What I will stop expecting of myself this month"}, {"id": "f5", "type": "textarea", "label": "Who I will tell about this so they can back me"}]'::jsonb, array['perinatal and postpartum', 'values', 'self-compassion']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('partner-load-conversation', 'Partner Load Conversation', 'couples'::resource_kind, 'A structured conversation for partners to lay out the visible and invisible work of a new baby.', 'Make the mental load visible before resentment does it.', array['Couples']::text[], '30 minutes', 'Have each partner list what they do, including the noticing and planning work, before either comments. Read the lists aloud without defending. The aim is one or two shifts, not a fair split by Friday. Return to it monthly for the first year.', '[{"id": "f0", "type": "textarea", "label": "Everything I do for the baby and household, including thinking and planning"}, {"id": "f1", "type": "textarea", "label": "What I did not know my partner was doing"}, {"id": "f2", "type": "textarea", "label": "What I most want taken off my plate"}, {"id": "f3", "type": "textarea", "label": "What I could take on"}, {"id": "f4", "type": "textarea", "label": "One change we agree for this month"}, {"id": "f5", "type": "textarea", "label": "How we will each say when the load tips again"}]'::jsonb, array['perinatal and postpartum', 'relationship issues', 'communication']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('birth-story-reflection', 'Birth Story Reflection', 'worksheet'::resource_kind, 'A paced, optional telling of the birth in the client''s own words, with the parts they want to keep and the parts they want help with.', 'Give a parent a way to say what the birth was like, at their pace, and to flag what still hurts.', array['Adults']::text[], 'Full session', 'Only offer it when the client wants to talk about the birth, and let them stop at any point. Do it in session, not as homework. Listen for what they feel they got wrong, since guilt is common and usually unearned. The last prompt tells you where further work is wanted.', '[{"id": "f0", "type": "textarea", "label": "What I expected the birth to be like"}, {"id": "f1", "type": "textarea", "label": "What happened, as much as I want to say"}, {"id": "f2", "type": "textarea", "label": "The moment that stays with me most"}, {"id": "f3", "type": "textarea", "label": "What I wish someone had said or done"}, {"id": "f4", "type": "textarea", "label": "What I got right"}, {"id": "f5", "type": "textarea", "label": "The part I still want help with"}]'::jsonb, array['perinatal and postpartum', 'narrative', 'PTSD and trauma']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('self-critic-voice-profile', 'Self-Critic Voice Profile', 'cbt'::resource_kind, 'Describes the inner critic as a character: what it says, when it shows up, and whose voice it borrows.', 'Put some distance between the client and the critic so its verdicts can be examined.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for the critic''s exact phrases and tone, then whose voice it sounds like; the answer is often a parent, teacher or ex. Ask what the critic thinks it is protecting the client from, which turns it from an enemy into a misguided guard. Follow with a kinder voice that is firm, not soppy.', '[{"id": "f0", "type": "textarea", "label": "What my critic says, in its exact words"}, {"id": "f1", "type": "textarea", "label": "When it is loudest"}, {"id": "f2", "type": "textarea", "label": "Whose voice it sounds like"}, {"id": "f3", "type": "textarea", "label": "What it thinks it is protecting me from"}, {"id": "f4", "type": "textarea", "label": "What it costs me"}, {"id": "f5", "type": "textarea", "label": "What a firm, fair coach would say instead"}, {"id": "f6", "type": "textarea", "label": "How I will answer the critic this week"}]'::jsonb, array['self-esteem', 'self-criticism', 'core beliefs']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('strengths-evidence-bank', 'Strengths Evidence Bank', 'worksheet'::resource_kind, 'A growing file of specific times the client showed a strength, kept as evidence against a harsh self-view.', 'Collect proof of strengths in a form the client cannot dismiss as flattery.', array['Adults', 'Teens']::text[], 'Ten minutes weekly', 'The entries must be specific events, not adjectives: the day they stayed calm when the meeting fell apart, not calm. Ask friends and family for entries too, in writing, and add them. Reread the bank before hard things and when the critic is loud.', '[{"id": "f0", "type": "textarea", "label": "A strength someone else would say I have"}, {"id": "f1", "type": "textarea", "label": "A specific time I showed it (what, where, who saw)"}, {"id": "f2", "type": "textarea", "label": "A strength I would grudgingly admit to"}, {"id": "f3", "type": "textarea", "label": "A specific time I showed that one"}, {"id": "f4", "type": "textarea", "label": "An entry from someone who knows me"}, {"id": "f5", "type": "textarea", "label": "How I will add to this each week"}]'::jsonb, array['self-esteem', 'strengths', 'evidence log']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('comparison-detox-log', 'Comparison Detox Log', 'cbt'::resource_kind, 'Tracks the moments the client compares themselves to others, the mood cost, and what they would rather measure themselves against.', 'Reduce the automatic upward comparisons that drain self-worth, especially online.', array['Adults', 'Teens']::text[], 'One week', 'Most comparisons happen on a phone, so the log usually points at a specific app and hour. Ask what the client actually knows about the person they compared themselves to, and what they were comparing: their inside to someone''s outside. The alternative measure is against their own last month, not against anyone.', '[{"id": "f0", "type": "textarea", "label": "Date, place and what I was looking at"}, {"id": "f1", "type": "textarea", "label": "Who I compared myself to, and on what"}, {"id": "f2", "type": "textarea", "label": "Mood before and after (0-10)"}, {"id": "f3", "type": "textarea", "label": "What I actually know about their life"}, {"id": "f4", "type": "textarea", "label": "What I was measuring, and whether it is fair"}, {"id": "f5", "type": "textarea", "label": "What I would rather measure myself against"}, {"id": "f6", "type": "textarea", "label": "One change to when or where I look at this"}]'::jsonb, array['self-esteem', 'social comparison', 'self-monitoring']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('values-not-verdicts', 'Values Not Verdicts', 'act'::resource_kind, 'Replaces global self-ratings with a look at what the client did in line with their values today.', 'Shift the client from grading themselves as a whole to noticing what they stand for.', array['Adults', 'Teens']::text[], '15 minutes', 'Catch the verdicts first: I am useless, I am a failure. Point out that a whole person cannot be graded like a test, then move to the day''s actions and the values they served. This is not a positive rating to replace a negative one; it is a refusal to rate.', '[{"id": "f0", "type": "textarea", "label": "The verdict my mind hands me most often"}, {"id": "f1", "type": "textarea", "label": "What evidence it uses"}, {"id": "f2", "type": "textarea", "label": "Three things I did today, and the value behind each"}, {"id": "f3", "type": "textarea", "label": "What I would say about a friend who did those things"}, {"id": "f4", "type": "textarea", "label": "The verdict, rewritten as a description of an action"}, {"id": "f5", "type": "textarea", "label": "One value I will act on tomorrow regardless of the verdict"}]'::jsonb, array['self-esteem', 'values', 'defusion']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('strength-spotting-circle', 'Strength Spotting Circle', 'game'::resource_kind, 'Players take turns naming a strength they saw another player use in the session or group, with the evidence.', 'Practice hearing specific positive feedback and letting it land.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'Go around twice. The speaker must give the evidence, not just the adjective, and the receiver may only say thank you. Watch for deflection and gently stop it. In individual work, play it between client and clinician, taking your turn honestly. Ask afterward which strength surprised the receiver.', '[{"id": "f0", "type": "textarea", "label": "A strength someone spotted in me, and the evidence"}, {"id": "f1", "type": "textarea", "label": "What I wanted to say instead of thank you"}, {"id": "f2", "type": "textarea", "label": "A strength I spotted in someone else"}, {"id": "f3", "type": "textarea", "label": "The one that surprised me"}, {"id": "f4", "type": "textarea", "label": "What I will do with it this week"}]'::jsonb, array['self-esteem', 'strengths', 'group', 'play']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('attention-focus-shift-practice', 'Attention Focus Shift Practice', 'cbt'::resource_kind, 'Trains the client to move attention from monitoring themselves to the person and the room during conversations.', 'Reduce self-focused attention, which feeds both the anxiety and the sense of performing badly.', array['Adults', 'Teens']::text[], 'One week', 'Demonstrate in session: have a two-minute conversation with attention fully inward, then repeat with attention on your face, words and the room, and compare the anxiety ratings. Set graded practices for the week. The log question about what the client noticed in the other person is the proof it worked.', '[{"id": "f0", "type": "textarea", "label": "The conversation I practiced in"}, {"id": "f1", "type": "textarea", "label": "Where my attention was at the start (0 = all on me, 10 = all on them)"}, {"id": "f2", "type": "textarea", "label": "What I shifted attention to"}, {"id": "f3", "type": "textarea", "label": "Three things I noticed about the other person or the room"}, {"id": "f4", "type": "textarea", "label": "Anxiety at the start and at the end (0-10)"}, {"id": "f5", "type": "textarea", "label": "What I would have missed if I had stayed inside my head"}]'::jsonb, array['social anxiety', 'attention', 'exposure']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('post-event-rumination-stopper', 'Post-Event Rumination Stopper', 'cbt'::resource_kind, 'A plan for the replay after a social event: what the client will and will not review, and for how long.', 'Cut short the hours of replaying a conversation and rewriting it as a disaster.', array['Adults', 'Teens']::text[], '15 minutes', 'Explain that the post-mortem is where the day''s real damage is done, since it rewrites a fine event as a failure. Agree a two-minute review with two questions only: what actually happened, and what would a kind observer say. Then a physical switch. Practice on the last event the client replayed.', '[{"id": "f0", "type": "textarea", "label": "The event I keep replaying"}, {"id": "f1", "type": "textarea", "label": "What I replay most (a sentence, a look, a pause)"}, {"id": "f2", "type": "textarea", "label": "My two-minute review: what actually happened"}, {"id": "f3", "type": "textarea", "label": "What a kind observer would say"}, {"id": "f4", "type": "textarea", "label": "My switch when the two minutes are up"}, {"id": "f5", "type": "textarea", "label": "How long the replay used to last, and how long it lasted this time"}]'::jsonb, array['social anxiety', 'rumination', 'thinking traps']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('social-prediction-log', 'Social Prediction Log', 'cbt'::resource_kind, 'Records the client''s forecast before a social situation and the outcome after, to compare over weeks.', 'Build the client''s own evidence that their predictions run far worse than events.', array['Adults', 'Teens']::text[], 'Two weeks', 'The forecast must be specific and rated: they will notice me blushing and think less of me, seventy percent. Afterward the client records what observably happened, not how it felt. Review the gap across ten entries, which is usually where belief shifts rather than in any single event.', '[{"id": "f0", "type": "textarea", "label": "The upcoming situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen, specifically"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0-100%)"}, {"id": "f3", "type": "textarea", "label": "What observably happened"}, {"id": "f4", "type": "textarea", "label": "How I know (what people said or did)"}, {"id": "f5", "type": "textarea", "label": "How the prediction compared"}, {"id": "f6", "type": "textarea", "label": "What I predict next time, adjusted"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'evidence']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('conversation-toolkit-card', 'Conversation Toolkit Card', 'dbt'::resource_kind, 'A pocket card of openers, follow-up questions and graceful exits for social situations.', 'Reduce the load of inventing conversation so the client can practice being in it.', array['Adults', 'Teens']::text[], '15 minutes to build', 'Build it with the client''s own words, not scripts from a book, and include exits, since knowing they can leave makes staying easier. Warn against using it as a safety behavior: the card is for learning, and the goal is to need it less. Rehearse a full opener-question-exit in session.', '[{"id": "f0", "type": "textarea", "label": "Three openers I could actually say"}, {"id": "f1", "type": "textarea", "label": "Three follow-up questions that work in most conversations"}, {"id": "f2", "type": "textarea", "label": "Two ways to leave a conversation gracefully"}, {"id": "f3", "type": "textarea", "label": "What I will do with my hands"}, {"id": "f4", "type": "textarea", "label": "The one I will try first this week"}, {"id": "f5", "type": "textarea", "label": "How it went, and whether I needed the card"}]'::jsonb, array['social anxiety', 'communication', 'skills']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('social-brave-steps-for-teens', 'Social Brave Steps for Teens', 'kids'::resource_kind, 'A teen''s own ladder of social situations from easy to hard, with a brave step per week.', 'Give a teenager a graded, self-chosen path back into the social situations they have been dodging.', array['Teens']::text[], '25 minutes', 'Let the teen build and order the steps; a ladder chosen by an adult will not be climbed. Keep parents to a support role agreed on the sheet. Steps should be specific: ask one question in class, not participate more. Celebrate attempts, not outcomes, and expect a step to be repeated before moving up.', '[{"id": "f0", "type": "textarea", "label": "Situations I have been avoiding"}, {"id": "f1", "type": "textarea", "label": "My ladder, easiest at the bottom"}, {"id": "f2", "type": "textarea", "label": "This week''s step"}, {"id": "f3", "type": "textarea", "label": "What I am afraid will happen"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What my parent will do (and not do) to help"}, {"id": "f6", "type": "textarea", "label": "The step for next week"}]'::jsonb, array['social anxiety', 'exposure', 'teens']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('continuing-bonds-letter', 'Continuing Bonds Letter', 'worksheet'::resource_kind, 'A letter to the person who died, about what has happened since and what the client still carries of them.', 'Support an ongoing connection with the person rather than a closing of the door.', array['Adults', 'Teens']::text[], '30 minutes', 'Offer it as one option among several, since some clients find writing to the dead unbearable and others find it the only thing that helps. Frame the bond as something that changes rather than ends. The client decides whether to read it aloud, keep it, or take it somewhere. Include 988 among the prompts for the darkest hours.', '[{"id": "f0", "type": "textarea", "label": "What I want to tell you about since you died"}, {"id": "f1", "type": "textarea", "label": "What I have kept of you (a habit, a phrase, an object, a way of seeing)"}, {"id": "f2", "type": "textarea", "label": "What I wish I had said"}, {"id": "f3", "type": "textarea", "label": "What I think you would say to me now"}, {"id": "f4", "type": "textarea", "label": "How I will keep you in my life going forward"}, {"id": "f5", "type": "textarea", "label": "If the grief ever gets dangerously dark: 988 (call or text), and who else I will reach"}]'::jsonb, array['grief and loss', 'continuing bonds', 'narrative']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('grief-triggers-calendar', 'Grief Triggers Calendar', 'worksheet'::resource_kind, 'A year at a glance with the dates, seasons and events likely to bring the grief up hard.', 'Let the client see the hard days coming and plan support for them instead of being ambushed.', array['Adults', 'Teens']::text[], '20 minutes', 'Include the obvious dates and the sideways ones: the first snow, the tax season the person used to handle, the song at the store. Plan for the week before an anniversary, which is often worse than the day. Decide with the client who will know about each date.', '[{"id": "f0", "type": "textarea", "label": "Anniversaries and birthdays"}, {"id": "f1", "type": "textarea", "label": "Seasons, holidays and rituals that will be different"}, {"id": "f2", "type": "textarea", "label": "Sideways reminders I can predict"}, {"id": "f3", "type": "textarea", "label": "The next hard date, and what I will do that day"}, {"id": "f4", "type": "textarea", "label": "Who will know it is coming"}, {"id": "f5", "type": "textarea", "label": "What helped on the last hard date, and what did not"}]'::jsonb, array['grief and loss', 'triggers', 'planning']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('dual-process-week-planner', 'Dual Process Week Planner', 'worksheet'::resource_kind, 'A week planned with time for facing the loss and time for the ordinary business of living, both on purpose.', 'Normalize moving between grief and daily life instead of feeling guilty about either.', array['Adults', 'Teens']::text[], '20 minutes', 'Explain that healthy grief moves between the loss and the rest of life, and that neither side is avoidance. Clients stuck on one side feel guilty when they laugh, or numb when they cannot cry; the planner gives both permission. Keep the entries small and concrete.', '[{"id": "f0", "type": "textarea", "label": "Times this week I will let myself be with the loss (looking at photos, visiting, talking about them)"}, {"id": "f1", "type": "textarea", "label": "Times this week I will do ordinary or even pleasant things"}, {"id": "f2", "type": "textarea", "label": "The side I tend to get stuck on"}, {"id": "f3", "type": "textarea", "label": "What guilt says when I switch sides"}, {"id": "f4", "type": "textarea", "label": "What I will say back to it"}, {"id": "f5", "type": "textarea", "label": "How the week went"}]'::jsonb, array['grief and loss', 'dual process', 'scheduling']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('memory-box-project', 'Memory Box Project', 'kids'::resource_kind, 'A child decorates a box and fills it with objects, drawings and stories that hold the person who died.', 'Give a grieving child a concrete, permitted place for their memories and a way to talk about them.', array['Children', 'Teens']::text[], '30 minutes to start, then ongoing', 'Let the child lead on what goes in and what stays private. Each item comes with a story the child tells if they want to; the telling is the work. Involve the surviving parent or carer where possible, and coach them to follow the child''s pace rather than their own. Revisit the box on hard dates.', '[{"id": "f0", "type": "textarea", "label": "What my box looks like"}, {"id": "f1", "type": "textarea", "label": "The first three things I put in it, and why"}, {"id": "f2", "type": "textarea", "label": "A story that goes with one of them"}, {"id": "f3", "type": "textarea", "label": "Something I want to ask about the person who died"}, {"id": "f4", "type": "textarea", "label": "Who I can open the box with"}, {"id": "f5", "type": "textarea", "label": "When I might want to open it"}]'::jsonb, array['grief and loss', 'children', 'memory', 'art']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('grief-conversation-cards', 'Grief Conversation Cards', 'game'::resource_kind, 'A deck of gentle prompts about the person who died, drawn in turn by family members or a group.', 'Let a family or group talk about the person in a structured, low-pressure way.', array['Children', 'Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Write the prompts with the group first so nothing on a card ambushes anyone, mixing light ones with heavier ones. Any card can be passed. Play in a circle with a talking object. In families, children often answer more freely than adults, which gives the adults permission.', '[{"id": "f0", "type": "textarea", "label": "Prompts we put on the cards"}, {"id": "f1", "type": "textarea", "label": "The card I drew, and what I said"}, {"id": "f2", "type": "textarea", "label": "Something I learned about the person from someone else"}, {"id": "f3", "type": "textarea", "label": "A card I passed on"}, {"id": "f4", "type": "textarea", "label": "The card I would like to answer next time"}]'::jsonb, array['grief and loss', 'family', 'play', 'group']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('needs-inventory-for-partners', 'Needs Inventory for Partners', 'couples'::resource_kind, 'Each partner lists their needs in the relationship, ranked, and guesses their partner''s list before comparing.', 'Replace assumed needs with stated ones, and show each partner what the other has been guessing.', array['Couples']::text[], '30 minutes', 'Have both partners complete it separately, including the guess about each other, before any discussion. The gaps between the guess and the real list are the material. Keep the tone of curiosity when a partner''s need surprises the other; surprise is information, not an accusation.', '[{"id": "f0", "type": "textarea", "label": "My top five needs in this relationship, ranked"}, {"id": "f1", "type": "textarea", "label": "How well each is being met right now (0-10)"}, {"id": "f2", "type": "textarea", "label": "What I think my partner''s top five are"}, {"id": "f3", "type": "textarea", "label": "What surprised me about their real list"}, {"id": "f4", "type": "textarea", "label": "One need of theirs I could meet better this month"}, {"id": "f5", "type": "textarea", "label": "One need of mine I will ask for directly"}]'::jsonb, array['relationship issues', 'needs', 'communication']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('perpetual-problems-sorter', 'Perpetual Problems Sorter', 'couples'::resource_kind, 'Sorts a couple''s recurring arguments into the solvable and the perpetual, and plans a different approach to each.', 'Stop a couple from trying to solve what needs managing, and from managing what could be solved.', array['Couples']::text[], '25 minutes', 'List the arguments first, then sort. Perpetual problems come from differences in personality or values and will be there in ten years; the goal is dialogue and humor about them, not a fix. Solvable problems get a concrete plan. Most couples are relieved to hear that having perpetual problems is normal.', '[{"id": "f0", "type": "textarea", "label": "Arguments we have more than once a month"}, {"id": "f1", "type": "textarea", "label": "Which of these come from a difference in who we are"}, {"id": "f2", "type": "textarea", "label": "Which could actually be solved with a plan"}, {"id": "f3", "type": "textarea", "label": "For one solvable problem: our plan"}, {"id": "f4", "type": "textarea", "label": "For one perpetual problem: what we can each accept"}, {"id": "f5", "type": "textarea", "label": "How we will talk about the perpetual one next time it comes up"}]'::jsonb, array['relationship issues', 'conflict', 'Gottman']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('trust-rebuilding-steps', 'Trust Rebuilding Steps', 'couples'::resource_kind, 'A shared ladder of specific, observable actions that would rebuild trust after a breach, with a timeline.', 'Turn a vague demand to earn trust back into steps both partners can see happening.', array['Couples']::text[], 'Full session', 'The hurt partner names what would help; the other partner says what they can commit to. Steps must be observable, since promises to change are not. Agree how long the checking phase lasts, because trust cannot rebuild under permanent surveillance. Review progress monthly in session.', '[{"id": "f0", "type": "textarea", "label": "What was broken, in one sentence each"}, {"id": "f1", "type": "textarea", "label": "Actions that would help me trust again (specific and visible)"}, {"id": "f2", "type": "textarea", "label": "Which of these I can commit to, and when"}, {"id": "f3", "type": "textarea", "label": "What transparency looks like for now, and for how long"}, {"id": "f4", "type": "textarea", "label": "What I need to hear when I have a wobble"}, {"id": "f5", "type": "textarea", "label": "How we will mark progress"}]'::jsonb, array['relationship issues', 'trust', 'repair']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('communication-pattern-replay', 'Communication Pattern Replay', 'couples'::resource_kind, 'Replays one recent exchange line by line, with each partner naming what they meant and what they heard.', 'Show a couple the gap between what was said, what was meant and what landed.', array['Couples']::text[], '30 minutes', 'Pick a short exchange, not the biggest fight. Write the actual lines, then have each partner add what they meant and what they heard. The gaps are usually where the fight lives. Finish by rewriting two lines each, and rehearse the rewrite in session.', '[{"id": "f0", "type": "textarea", "label": "The exchange, line by line, as it happened"}, {"id": "f1", "type": "textarea", "label": "For my lines: what I meant"}, {"id": "f2", "type": "textarea", "label": "For their lines: what I heard"}, {"id": "f3", "type": "textarea", "label": "Where the gap between meant and heard was widest"}, {"id": "f4", "type": "textarea", "label": "Two lines I would rewrite"}, {"id": "f5", "type": "textarea", "label": "How the rewritten version sounds out loud"}]'::jsonb, array['relationship issues', 'communication', 'pattern']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('relationship-values-compass', 'Relationship Values Compass', 'act'::resource_kind, 'Each partner names the kind of partner they want to be, separately from how the other is behaving.', 'Anchor each partner to their own values so change does not wait on the other person moving first.', array['Couples', 'Adults']::text[], '20 minutes', 'Works with a couple or with one partner alone. The key move is separating my values as a partner from what I get back; clients often discover they have been acting on a scoreboard. Choose one valued action for the week that does not depend on the other person''s response.', '[{"id": "f0", "type": "textarea", "label": "The partner I want to be, in three words"}, {"id": "f1", "type": "textarea", "label": "How I have actually been acting lately"}, {"id": "f2", "type": "textarea", "label": "What I have been waiting for my partner to do first"}, {"id": "f3", "type": "textarea", "label": "One valued action I will take this week regardless"}, {"id": "f4", "type": "textarea", "label": "What my mind says will happen if I go first"}, {"id": "f5", "type": "textarea", "label": "What actually happened"}]'::jsonb, array['relationship issues', 'values', 'committed action']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('safety-and-stabilization-plan', 'Safety and Stabilization Plan', 'worksheet'::resource_kind, 'A plan for the practical and emotional safety a survivor needs in place before any deeper work.', 'Put steady ground under the client first: who, where, what, and what to do when it gets too much.', array['Adults', 'Teens']::text[], 'Full session', 'Complete it together in session and never as homework. Cover present-day safety from the person who harmed them, the people who help, the skills that bring them back, and what to do in the worst hours. Move at the client''s pace and do not ask for the details of what happened; that is not what this sheet is for. Include 988.', '[{"id": "f0", "type": "textarea", "label": "Am I safe from the person now? What would make me safer"}, {"id": "f1", "type": "textarea", "label": "People I trust, and what each one can help with"}, {"id": "f2", "type": "textarea", "label": "Skills that bring me back when I am flooded"}, {"id": "f3", "type": "textarea", "label": "Signs that I am doing too much too fast"}, {"id": "f4", "type": "textarea", "label": "What I will do in the worst hour: 988 (call or text), and my other numbers"}, {"id": "f5", "type": "textarea", "label": "What I want my therapist to know about pace"}, {"id": "f6", "type": "textarea", "label": "What I am not ready to talk about yet, and that is fine"}]'::jsonb, array['sexual abuse', 'PTSD and trauma', 'safety planning']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('consent-and-boundaries-map', 'Consent and Boundaries Map', 'worksheet'::resource_kind, 'Maps the client''s yes, no and maybe across touch, closeness and conversation, in their own words.', 'Help a survivor reclaim the right to decide, in small everyday ways, what they allow and what they do not.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep it to everyday boundaries at first: hugs, sitting close, questions from family, who has their number. The maybe column matters, since survivors often feel boundaries must be absolute to count. Rehearse one no in session. Nothing here asks about the abuse itself.', '[{"id": "f0", "type": "textarea", "label": "Things I am a clear yes to"}, {"id": "f1", "type": "textarea", "label": "Things I am a clear no to"}, {"id": "f2", "type": "textarea", "label": "Things that are a maybe, and what would make them a yes"}, {"id": "f3", "type": "textarea", "label": "A boundary someone in my life keeps crossing"}, {"id": "f4", "type": "textarea", "label": "How I will say no to that, in my words"}, {"id": "f5", "type": "textarea", "label": "What I will do if they push"}, {"id": "f6", "type": "textarea", "label": "Someone who respects my boundaries well"}]'::jsonb, array['sexual abuse', 'boundaries', 'consent']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('shame-response-sheet', 'Shame Response Sheet', 'cbt'::resource_kind, 'Catches the self-blame that follows abuse, tests it against what the client would say to another survivor, and writes the fairer version.', 'Loosen the belief that the client caused, allowed or deserved what happened.', array['Adults', 'Teens']::text[], '25 minutes', 'Do this in session, gently, and expect the double standard to be stark: the client will extend to another survivor a compassion they refuse themselves. Do not argue the client out of the belief; let the comparison do the work, and rate belief before and after. Stop if the client becomes flooded and return to grounding.', '[{"id": "f0", "type": "textarea", "label": "What I tell myself about why it happened"}, {"id": "f1", "type": "textarea", "label": "How much I believe that (0-100%)"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend who told me the same story"}, {"id": "f3", "type": "textarea", "label": "Where the blame actually belongs"}, {"id": "f4", "type": "textarea", "label": "The fairer statement, in my words"}, {"id": "f5", "type": "textarea", "label": "How much I believe the fairer statement now (0-100%)"}]'::jsonb, array['sexual abuse', 'shame', 'self-blame']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('support-disclosure-planner', 'Support Disclosure Planner', 'worksheet'::resource_kind, 'Plans whether, who, when and how much to tell, so a disclosure happens on the client''s terms.', 'Keep the choice of who knows, and how much, in the survivor''s hands.', array['Adults', 'Teens']::text[], '25 minutes', 'Not telling is a valid outcome of this sheet and should be said out loud. Work through what the client wants from telling, who is likely to respond well, and how much to say; a first sentence and an exit line are worth rehearsing. Plan for the reaction being disappointing, since it sometimes is.', '[{"id": "f0", "type": "textarea", "label": "What I hope telling someone would give me"}, {"id": "f1", "type": "textarea", "label": "People I might tell, and how I think each would respond"}, {"id": "f2", "type": "textarea", "label": "The person I would tell first, if anyone"}, {"id": "f3", "type": "textarea", "label": "How much I want to say (a sentence is enough)"}, {"id": "f4", "type": "textarea", "label": "My first sentence"}, {"id": "f5", "type": "textarea", "label": "How I will end the conversation if I need to"}, {"id": "f6", "type": "textarea", "label": "What I will do for myself afterward, whatever their reaction"}]'::jsonb, array['sexual abuse', 'disclosure', 'support']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-safety-rules-poster', 'Body Safety Rules Poster', 'kids'::resource_kind, 'A child makes a poster of body safety rules: private parts, okay and not-okay touch, secrets versus surprises, and who to tell.', 'Teach a child the words and the permission to tell, as part of prevention work with families.', array['Children']::text[], '30 minutes', 'A prevention and education tool, done with a parent in the room where possible. Use correct names for body parts. Teach that surprises are fun and short and secrets about bodies are never kept. List five trusted adults. If a child discloses during this, stop the activity, stay calm, believe them, and follow your mandated reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Private parts have proper names, and mine are"}, {"id": "f1", "type": "textarea", "label": "Okay touch and not-okay touch: my examples"}, {"id": "f2", "type": "textarea", "label": "The difference between a surprise and a secret"}, {"id": "f3", "type": "textarea", "label": "My five trusted grown-ups"}, {"id": "f4", "type": "textarea", "label": "What I say if someone breaks a body safety rule"}, {"id": "f5", "type": "textarea", "label": "Where my poster will hang"}]'::jsonb, array['sexual abuse', 'children', 'body safety', 'prevention']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('coping-menu-by-situation', 'Coping Menu by Situation', 'dbt'::resource_kind, 'A menu of the client''s coping options sorted by where they are: at work, in public, at home, in bed.', 'Match skills to settings so the right one is available where the distress actually happens.', array['Adults', 'Teens']::text[], '20 minutes', 'Most clients have skills that only work at home and distress that happens elsewhere. Sort by setting and check that each setting has at least two options that are invisible to other people. Include one for the middle of the night. Keep the menu in the phone''s notes.', '[{"id": "f0", "type": "textarea", "label": "At work or school: two things I can do without anyone noticing"}, {"id": "f1", "type": "textarea", "label": "In public: two options"}, {"id": "f2", "type": "textarea", "label": "At home: two options"}, {"id": "f3", "type": "textarea", "label": "In bed at 3 a.m.: two options"}, {"id": "f4", "type": "textarea", "label": "The skill I reach for too often, and where it does not work"}, {"id": "f5", "type": "textarea", "label": "The new skill I will try this week, and where"}]'::jsonb, array['coping skills', 'distress tolerance', 'planning']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('skill-practice-log', 'Skill Practice Log', 'worksheet'::resource_kind, 'A weekly log of which coping skill the client used, in what situation, and how well it worked.', 'Turn coping from a vague resolve into a tracked practice with results.', array['Adults', 'Teens']::text[], 'One week', 'The rating is the useful part: a skill that scores three out of ten in three different situations can be retired without guilt. Look for the mismatch between skills tried and situations faced. Praise the attempt, especially when the skill did not work, since trying is what builds the habit.', '[{"id": "f0", "type": "textarea", "label": "Date and the situation"}, {"id": "f1", "type": "textarea", "label": "Distress before (0-10)"}, {"id": "f2", "type": "textarea", "label": "The skill I used"}, {"id": "f3", "type": "textarea", "label": "Distress after (0-10)"}, {"id": "f4", "type": "textarea", "label": "How well it worked (0-10) and why"}, {"id": "f5", "type": "textarea", "label": "A skill I could have used instead"}, {"id": "f6", "type": "textarea", "label": "The skill I will practice most next week"}]'::jsonb, array['coping skills', 'self-monitoring', 'skills']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('coping-ladder-for-kids', 'Coping Ladder for Kids', 'kids'::resource_kind, 'A ladder of a child''s coping moves from small feelings at the bottom to big ones at the top.', 'Match the size of the coping move to the size of the feeling, in a picture a child can use.', array['Children']::text[], '20 minutes', 'Draw a ladder with three or four rungs and let the child assign feelings sizes to each. Small feelings get small moves: a breath, a drink of water. Big feelings get big moves: a break, a grown-up. Practice one move per rung in session and have the parent post the ladder at home.', '[{"id": "f0", "type": "textarea", "label": "Bottom rung: a small feeling and my small move"}, {"id": "f1", "type": "textarea", "label": "Middle rung: a medium feeling and my medium move"}, {"id": "f2", "type": "textarea", "label": "Top rung: a huge feeling and my biggest move"}, {"id": "f3", "type": "textarea", "label": "How I know which rung I am on"}, {"id": "f4", "type": "textarea", "label": "Who helps me on the top rung"}, {"id": "f5", "type": "textarea", "label": "Where my ladder is posted"}]'::jsonb, array['coping skills', 'children', 'regulation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('coping-skills-relay', 'Coping Skills Relay', 'game'::resource_kind, 'Teams race to act out or demonstrate a coping skill for each situation card drawn.', 'Rehearse coping skills under mild pressure and laughter, so they are practiced rather than just known.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Write situation cards with the group beforehand: a test tomorrow, a friend ignoring a text, a loud house. A team scores when the skill fits the situation and could actually be done there. Judge fit, not speed, and let the group argue the call; the argument is the learning.', '[{"id": "f0", "type": "textarea", "label": "Situation cards we made"}, {"id": "f1", "type": "textarea", "label": "Skills my team demonstrated"}, {"id": "f2", "type": "textarea", "label": "A skill another team showed that I want to steal"}, {"id": "f3", "type": "textarea", "label": "A situation none of us could match well"}, {"id": "f4", "type": "textarea", "label": "The skill I will practice this week"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('helpful-vs-costly-coping-sort', 'Helpful vs Costly Coping Sort', 'act'::resource_kind, 'Sorts everything the client does to feel better into what helps in the long run and what costs more than it gives.', 'Help the client judge coping by its long-term workability rather than by how fast it works.', array['Adults', 'Teens']::text[], '20 minutes', 'List everything without judgment first, including the ones the client is ashamed of; those are usually the fastest-acting. Sort by long-term workability, not by how they look. Most clients find a few things belong in both columns depending on amount, which is worth writing down rather than resolving.', '[{"id": "f0", "type": "textarea", "label": "Everything I do to feel better, fast or slow"}, {"id": "f1", "type": "textarea", "label": "Which ones help me next week too"}, {"id": "f2", "type": "textarea", "label": "Which ones cost more than they give"}, {"id": "f3", "type": "textarea", "label": "Which ones depend on how much"}, {"id": "f4", "type": "textarea", "label": "One costly one I will shrink, and how"}, {"id": "f5", "type": "textarea", "label": "One helpful one I will do more of, and when"}]'::jsonb, array['coping skills', 'workability', 'values']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('phobia-prediction-tracker', 'Phobia Prediction Tracker', 'cbt'::resource_kind, 'Records what the client expects to happen around the feared object or situation and what actually occurs.', 'Build the client''s own evidence that the feared outcome and the felt danger diverge.', array['Adults', 'Teens']::text[], 'Two weeks', 'Ask for the specific feared outcome, not just fear: I will faint, the dog will bite, the plane will crash. Rate belief before and after each approach. The pattern across entries is what changes belief, so aim for at least eight entries before drawing conclusions together.', '[{"id": "f0", "type": "textarea", "label": "The feared thing and the situation"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen, specifically"}, {"id": "f2", "type": "textarea", "label": "How sure I am (0-100%)"}, {"id": "f3", "type": "textarea", "label": "Peak fear (0-10)"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "What I did during the peak"}, {"id": "f6", "type": "textarea", "label": "My belief in the prediction now (0-100%)"}]'::jsonb, array['phobias', 'behavioral experiment', 'evidence']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('approach-steps-planner', 'Approach Steps Planner', 'cbt'::resource_kind, 'Plans the next approach step toward a feared object in detail: where, how long, with whom, and what to drop.', 'Make each approach step concrete enough to actually happen this week.', array['Adults', 'Teens']::text[], '15 minutes', 'One step at a time, planned to the minute. Include what safety moves the client will drop, since carrying the escape plan into the step blunts it. Decide in advance how long to stay: long enough for the fear to fall, not just to touch and run. Debrief in session before planning the next.', '[{"id": "f0", "type": "textarea", "label": "This week''s step"}, {"id": "f1", "type": "textarea", "label": "Where and when, exactly"}, {"id": "f2", "type": "textarea", "label": "Who will be there, and what they will and will not do"}, {"id": "f3", "type": "textarea", "label": "How long I will stay (until fear drops by half)"}, {"id": "f4", "type": "textarea", "label": "The safety moves I will not use"}, {"id": "f5", "type": "textarea", "label": "What happened, and what I will do next week"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('phobia-body-response-sheet', 'Phobia Body Response Sheet', 'worksheet'::resource_kind, 'Names what the client''s body does around the feared thing, and separates the alarm from the danger.', 'Help the client see the fear response as an alarm that can fire without a fire.', array['Adults', 'Teens', 'Children']::text[], '15 minutes', 'Map the response: heart, breath, muscles, stomach, the urge to run. Explain plainly that the body''s alarm is doing its job and that the job is to get them out, which is why staying feels wrong. For blood or needle fears, note the faint response and plan applied tension separately.', '[{"id": "f0", "type": "textarea", "label": "What my body does first around the feared thing"}, {"id": "f1", "type": "textarea", "label": "What it does next"}, {"id": "f2", "type": "textarea", "label": "The urge that comes with it"}, {"id": "f3", "type": "textarea", "label": "What the alarm is trying to make me do"}, {"id": "f4", "type": "textarea", "label": "What I know about the real danger in this situation"}, {"id": "f5", "type": "textarea", "label": "What I will do with the alarm next time it fires"}]'::jsonb, array['phobias', 'body awareness', 'psychoeducation']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('brave-practice-chart-for-kids', 'Brave Practice Chart for Kids', 'kids'::resource_kind, 'A sticker chart for a child''s repeated brave practices with a feared thing, tied to a small reward.', 'Make repetition of approach steps visible and rewarding for a child.', array['Children']::text[], '20 minutes to set up, then daily', 'Choose practices small enough to repeat daily: look at a picture of a dog, stand in the doorway with the lights off. Stickers go on for attempts, not for calm. Parents hold the chart and the reward and keep their own anxiety out of the practice. Change the practice when it stops earning fear.', '[{"id": "f0", "type": "textarea", "label": "My brave practice this week"}, {"id": "f1", "type": "textarea", "label": "Stickers I earned"}, {"id": "f2", "type": "textarea", "label": "How scared I was the first time (0-10) and the last time"}, {"id": "f3", "type": "textarea", "label": "My reward when the chart is full"}, {"id": "f4", "type": "textarea", "label": "What my grown-up does during practice"}, {"id": "f5", "type": "textarea", "label": "Next week''s brave practice"}]'::jsonb, array['phobias', 'children', 'exposure', 'parenting']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('fear-ladder-card-sort', 'Fear Ladder Card Sort', 'game'::resource_kind, 'Situations written on cards and physically sorted into a ladder from least to most scary.', 'Build a fear hierarchy as a hands-on sorting task rather than a form.', array['Children', 'Teens', 'Adults']::text[], '20 minutes', 'Write one situation per card with the client, at least fifteen, then sort them on the table or floor. The physical sorting draws out distinctions a form misses, and the client can move cards as beliefs change. Photograph the finished ladder and use it to choose the next approach step.', '[{"id": "f0", "type": "textarea", "label": "Situations we wrote on cards"}, {"id": "f1", "type": "textarea", "label": "The bottom three cards"}, {"id": "f2", "type": "textarea", "label": "The top three cards"}, {"id": "f3", "type": "textarea", "label": "Cards I moved while sorting, and why"}, {"id": "f4", "type": "textarea", "label": "The card I will start with"}, {"id": "f5", "type": "textarea", "label": "The card I cannot imagine reaching yet"}]'::jsonb, array['phobias', 'hierarchy', 'play']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-neutrality-practice', 'Body Neutrality Practice', 'act'::resource_kind, 'Daily short statements about what the body did today rather than how it looked.', 'Move the client''s relationship with their body from judgment toward function and use.', array['Adults', 'Teens']::text[], 'Two minutes daily for two weeks', 'Aim for neutral, not positive; clients who cannot believe their body is beautiful can believe it carried them up the stairs. Keep the statements about doing and feeling. Notice when the client sneaks an appearance comment in and gently redirect. Never mention weight, shape or food in this practice.', '[{"id": "f0", "type": "textarea", "label": "Three things my body did for me today"}, {"id": "f1", "type": "textarea", "label": "One thing it let me feel (warmth, music, a hug, the wind)"}, {"id": "f2", "type": "textarea", "label": "A neutral statement about my body, without judgment either way"}, {"id": "f3", "type": "textarea", "label": "What my mind wanted to add about how it looks"}, {"id": "f4", "type": "textarea", "label": "How I responded to that"}, {"id": "f5", "type": "textarea", "label": "The statement I will use tomorrow morning"}]'::jsonb, array['body image', 'acceptance', 'defusion']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-checking-log', 'Body Checking Log', 'cbt'::resource_kind, 'Records the mirror checks, pinching, comparing and photo scrutiny that keep body worry alive, and what each one did to mood.', 'Show the client how checking feeds the worry, and plan a reduction.', array['Adults', 'Teens']::text[], 'One week', 'Checking feels like getting information but produces worse mood almost every time; the log makes that visible. Include the quiet forms: reflections in windows, comparing in group photos, clothes tried and discarded. Plan one check to cut in half, not to stop entirely.', '[{"id": "f0", "type": "textarea", "label": "Date and time"}, {"id": "f1", "type": "textarea", "label": "What I checked, and how (mirror, pinch, photo, comparing)"}, {"id": "f2", "type": "textarea", "label": "What I was looking for"}, {"id": "f3", "type": "textarea", "label": "Mood before and after (0-10)"}, {"id": "f4", "type": "textarea", "label": "How long the reassurance lasted, if any"}, {"id": "f5", "type": "textarea", "label": "The check I will cut in half next week"}, {"id": "f6", "type": "textarea", "label": "What I will do instead in that moment"}]'::jsonb, array['body image', 'self-monitoring', 'maintenance']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('appearance-assumptions-sheet', 'Appearance Assumptions Sheet', 'cbt'::resource_kind, 'Lists the client''s rules linking appearance to worth, acceptance or success, and tests each one.', 'Loosen the beliefs that make appearance carry the whole weight of self-worth.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw out the if-then rules: if I looked different, then people would... Test each against the client''s own experience and the people they admire. The goal is to shrink the share of self-worth that appearance holds, which a pie chart of what makes up their worth can show before and after.', '[{"id": "f0", "type": "textarea", "label": "My rules about appearance (if I looked..., then...)"}, {"id": "f1", "type": "textarea", "label": "Where each rule came from"}, {"id": "f2", "type": "textarea", "label": "Evidence from my own life for and against it"}, {"id": "f3", "type": "textarea", "label": "People I admire, and how much their looks have to do with it"}, {"id": "f4", "type": "textarea", "label": "How much of my self-worth appearance holds now (%)"}, {"id": "f5", "type": "textarea", "label": "What else I would like it to rest on"}]'::jsonb, array['body image', 'core beliefs', 'self-esteem']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('body-gratitude-function-list', 'Body Gratitude Function List', 'worksheet'::resource_kind, 'A list of what the client''s body has carried them through, by life stage, written as a record rather than a rating.', 'Build a history of the body as a companion rather than an object under review.', array['Adults', 'Teens']::text[], '20 minutes', 'Move through life stages: childhood play, illness survived, work done, people carried, places reached. The tone is a record, not a pep talk. Clients with a history of harming or overworking their body may find this tender; slow down there. No comments on shape or size anywhere on the sheet.', '[{"id": "f0", "type": "textarea", "label": "What my body did for me as a child"}, {"id": "f1", "type": "textarea", "label": "What it has carried me through"}, {"id": "f2", "type": "textarea", "label": "What it lets me do that I would miss"}, {"id": "f3", "type": "textarea", "label": "Someone it has held or helped"}, {"id": "f4", "type": "textarea", "label": "Something it recovered from"}, {"id": "f5", "type": "textarea", "label": "What I would like to thank it for, plainly"}]'::jsonb, array['body image', 'gratitude', 'self-compassion']::text[], '2026-09-16T15:00:00+00:00'::timestamptz),
  ('media-diet-audit', 'Media Diet Audit', 'worksheet'::resource_kind, 'An inventory of the accounts, shows and images the client consumes, and what each does to how they feel in their body.', 'Change what the client feeds their body image, since much of it arrives through a screen.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through the phone together. For each account or habit, ask what it does to the client''s body feeling in the ten minutes after. Unfollowing is a real intervention and often the fastest one; replace, do not just remove, so the feed is not empty. Repeat in a month.', '[{"id": "f0", "type": "textarea", "label": "Accounts and shows I see most"}, {"id": "f1", "type": "textarea", "label": "How I feel in my body after each (better, worse, nothing)"}, {"id": "f2", "type": "textarea", "label": "The ones that leave me comparing"}, {"id": "f3", "type": "textarea", "label": "Accounts I will unfollow or mute this week"}, {"id": "f4", "type": "textarea", "label": "What I will follow instead (bodies doing things, other interests entirely)"}, {"id": "f5", "type": "textarea", "label": "How my feed feels after the change"}]'::jsonb, array['body image', 'social comparison', 'habits']::text[], '2026-09-16T15:00:00+00:00'::timestamptz)
